{
  "title": "The Gilded Ruin: A Rescue Through Temptation",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The ruined gates loom beneath a blood-red sky.",
      "visual_description": "Two massive iron gates, twisted and broken, stand half-open beneath a crimson sunset. Faded royal banners hang tattered from the battlements.",
      "characters": ["Kaelen", "Mira"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople huddle in a market square.",
      "visual_description": "A cobblestone square littered with overturned carts and scattered fruit. A group of gaunt townspeople press against a crumbling fountain, eyeing the shadows.",
      "characters": ["Townspeople"]
    },
    {
      "scene_number": 3,
      "caption": "Armored patrols march past a cursed tower.",
      "visual_description": "Three black-armored soldiers stride in lockstep before a spiral tower whose stones pulse with faint green light. Dust swirls around their boots.",
      "characters": ["Armored Soldier 1", "Armored Soldier 2", "Armored Soldier 3"]
    },
    {
      "scene_number": 4,
      "caption": "Kaelen and Mira slip through a side alley.",
      "visual_description": "A narrow alley strung with frayed laundry lines. Kaelen signals Mira to stop as a patrol passes the far end. Moss clings to the walls.",
      "characters": ["Kaelen", "Mira"]
    },
    {
      "scene_number": 5,
      "caption": "A magic door shimmers beside an old well.",
      "visual_description": "Stone-carved doorframe engraved with runes, the doorway filled with a swirling silver light. An ancient well stands nearby, its bucket rotted.",
      "characters": ["Kaelen", "Mira"]
    },
    {
      "scene_number": 6,
      "caption": "The heroes decide the magic door is too risky.",
      "visual_description": "Kaelen places a hand on the doorframe but pulls back as the runes flare. Mira shakes her head, pointing toward the castle interior.",
      "characters": ["Kaelen", "Mira"]
    },
    {
      "scene_number": 7,
      "caption": "Rumors of a dragon echo in a tavern cellar.",
      "visual_description": "Low-ceilinged cellar lit by a single candle. A hooded informant leans across a barrel, whispering. Dusty wine bottles line the walls.",
      "characters": ["Kaelen", "Mira", "Hooded Informant"]
    },
    {
      "scene_number": 8,
      "caption": "A dragon's shadow passes over the courtyard.",
      "visual_description": "Broad courtyard bathed in late afternoon light. A massive winged shadow sweeps across the flagstones. Soldiers scatter for cover.",
      "characters": ["Armored Soldier 1", "Armored Soldier 2", "Armored Soldier 3"]
    },
    {
      "scene_number": 9,
      "caption": "Kaelen and Mira climb the castle wall.",
      "visual_description": "Side of the ruined castle wall, ivy and broken masonry offering handholds. Kaelen reaches for a ledge; Mira braces below.",
      "characters": ["Kaelen", "Mira"]
    },
    {
      "scene_number": 10,
      "caption": "Inside the throne room, a cursed crown glows.",
      "visual_description": "Crumbled throne room with a shattered stained-glass window. A golden crown on a stone pedestal pulses with amber light. Dust motes hang in the air.",
      "characters": ["Kaelen", "Mira"]
    },
    {
      "scene_number": 11,
      "caption": "The heroes resist the temptation of the crown.",
      "visual_description": "Kaelen reaches for the crown, but Mira grabs his wrist. Her eyes are fixed on the crown's flickering shadow, which writhes like a serpent.",
      "characters": ["Kaelen", "Mira"]
    },
    {
      "scene_number": 12,
      "caption": "They find the prisoner in an underground cell.",
      "visual_description": "Dark cell with rusted bars and a straw-covered floor. A figure in chains sits against the far wall, head bowed.",
      "characters": ["Kaelen", "Mira", "Prisoner Elara"]
    },
    {
      "scene_number": 13,
      "caption": "Kaelen picks the lock while Mira watches the door.",
      "visual_description": "Close-up of Kaelen's hands working a lockpick into the cell door's mechanism. Mira stands alert at the stairway, sword half-drawn.",
      "characters": ["Kaelen", "Mira"]
    },
    {
      "scene_number": 14,
      "caption": "Patrols close in as they flee the dungeon.",
      "visual_description": "Torch-lit corridor, three armored soldiers running toward the camera. Kaelen, Mira, and Elara sprint the opposite way, past dripping walls.",
      "characters": ["Kaelen", "Mira", "Prisoner Elara", "Armored Soldier 1", "Armored Soldier 2", "Armored Soldier 3"]
    },
    {
      "scene_number": 15,
      "caption": "A magic door seals behind them, blocking pursuit.",
      "visual_description": "Stone doorway in a narrow passage; Kaelen slams his palm on a rune, and a sheet of blue light solidifies across the opening. Soldiers' silhouettes pound against it.",
      "characters": ["Kaelen", "Mira", "Prisoner Elara"]
    },
    {
      "scene_number": 16,
      "caption": "They emerge onto the bridge under moonlight.",
      "visual_description": "Long stone bridge arching over a dark river. Full moon reflects on the water. The ruined city looms behind them.",
      "characters": ["Kaelen", "Mira", "Prisoner Elara"]
    },
    {
      "scene_number": 17,
      "caption": "The dragon circles overhead as they cross.",
      "visual_description": "The three figures run across the bridge. Above, a dragon spirals down, its scales glinting silver and red. Wind whips their hair.",
      "characters": ["Kaelen", "Mira", "Prisoner Elara", "Dragon"]
    },
    {
      "scene_number": 18,
      "caption": "They reach the far side as the bridge crumbles.",
      "visual_description": "The trio stumbles onto grassy ground. Behind them, the bridge collapses into the river, and the dragon roars in frustration. Dawn breaks over distant hills.",
      "characters": ["Kaelen", "Mira", "Prisoner Elara"]
    }
  ]
}

